    def find_rectangles(self, removal_candidates, step=0.125):
        x_vals = [p[0] for p in removal_candidates]
        x_vals_uq = list(set(x_vals))
        x_vals_uq = sorted(x_vals_uq, key=lambda x: x)
        points_2d = []
        all_v_rects = set()  # vertical rectangles
        all_mid_vertices = set()
        single_edge_vertices = set()

        # stack all points by their x-value, e.g.:
        #_______0______________1______________2______
        # (5.25, 6.88) | (5.37, 3.50) | (5.88, 3.50)
        # (5.25, 6.75) | (5.37, 3.62) | (5.88, 3.62)
        # (5.25, 6.62) |              | (5.88, 3.75)
        #
        for i in range(len(x_vals_uq)):
            new_col = [bp for bp in removal_candidates if bp[0] == x_vals_uq[i]]
            new_col = sorted(new_col, key = lambda x: x[1])
            #print(new_col)
            points_2d.append(new_col)
        #print("points_2d: ", points_2d)

        # find vertical rectangles
        for i in range(len(x_vals_uq) - 1):
            cur_col = points_2d[i]
            next_col = points_2d[i + 1]

            # if two columns are x-neighbours, then inspect their y-values
            if len(cur_col) > 0 and len(next_col) > 0 and next_col[0][0] - cur_col[0][0] < 1.5 * step:
                for cc in range(len(cur_col) - 1):
                    rect_start = None
                    rect_end = None
                    for nc in range (len(next_col) - 1):
                        if (cur_col[cc][1] == next_col[nc][1] and # if y coordinates are the same in current and next column
                            cur_col[cc + 1][1] == next_col[nc + 1][1] and # and next y coordinates are also the same
                            cur_col[cc + 1][1] - cur_col[cc][1] < 1.5 * step): # and the difference is within a step, then it is forming a square
                            # we found a square with these vertices: cur_col[cc], next_col[nc], cur_col[cc + 1], next_col[nc + 1]
                            # let's keep going to see if this continues into a rectangle.
                            rect_start = (cur_col[cc], next_col[nc])
                            rect_step_count = 1 # so far we have two pairs of points (two steps in the potential rectangle), which at this point is a square, but we have registered only one (rect_start)
                            while (cc + rect_step_count < len(cur_col) and # while we haven't run out of current column
                                   nc + rect_step_count < len(next_col) and # and haven't run out of next column
                                   cur_col[cc + rect_step_count][1] == next_col[nc + rect_step_count][1] and # and the next pair down still forms further part of this rectangle
                                   cur_col[cc + rect_step_count][1] - cur_col[cc + rect_step_count - 1][1] < 1.5 * step): # and the difference between this and next pair is within a step
                                rect_end = (cur_col[cc + rect_step_count], next_col[nc + rect_step_count])
                                all_mid_vertices.add(rect_end[0])
                                all_mid_vertices.add(rect_end[1])
                                #print("detected: ", cur_col[cc + rect_step_count], next_col[nc + rect_step_count])
                                single_edge_vertices.add(rect_end[0])
                                rect_step_count += 1
                            if rect_step_count > 2: # if we have discovered anything bigger than a square
                                # if this start has not already been seen much earlier as a mid section of a different rectangle, then add
                                # both the start and end to the detected rectangle vertices.
                                if rect_start[0] not in all_mid_vertices:
                                    all_v_rects.add(rect_start[0])
                                    all_v_rects.add(rect_start[1])
                                    all_v_rects.add(rect_end[0])
                                    all_v_rects.add(rect_end[1])
                            # else:
                            #     # if the only thing we found was a square, then take out rect_end from all_mid_vertices because
                            #     # it is not a mid vertice
                            #     pass
                            # remove last rect_end that we added to all_mid_vertices, because they are supposed to be mid vertices only
                            all_mid_vertices.discard(rect_end[0])
                            all_mid_vertices.discard(rect_end[1])
                            single_edge_vertices.discard(rect_end[0])

                            #print("all_mid_vertices: ", all_mid_vertices)

        #print("all_v_rects: ", all_v_rects)
        # print("all_mid_vertices: ", all_mid_vertices)
        # print("single_edge_vertices", single_edge_vertices)
        return all_v_rects, single_edge_vertices

    def remove_1_edge_from_rectangle(self, removal_candidates, step=0.125):
        x_vals = [p[0] for p in removal_candidates]
        x_vals_uq = list(set(x_vals))
        x_vals_uq = sorted(x_vals_uq, key=lambda x: x)
        points_2d = []
        all_v_rects = set()  # vertical rectangles
        all_mid_vertices = set()

        # stack all points by their x-value, e.g.:
        #_______0______________1______________2______
        # (5.25, 6.88) | (5.37, 3.50) | (5.88, 3.50)
        # (5.25, 6.75) | (5.37, 3.62) | (5.88, 3.62)
        # (5.25, 6.62) |              | (5.88, 3.75)
        #
        for i in range(len(x_vals_uq)):
            new_col = [bp for bp in removal_candidates if bp[0] == x_vals_uq[i]]
            new_col = sorted(new_col, key = lambda x: x[1])
            #print(new_col)
            points_2d.append(new_col)
        print("points_2d: ", points_2d)

    def find_room_perimeter_path(self, reachable_room_points, unreachable_room_points, room_of_placement):
        # First let's establish the boundaries between walkable and non-walkable locations in the room
        boundary_points = self.get_room_perimeter_points_1st_pass(reachable_room_points, unreachable_room_points,
                                                                room_of_placement, self.na)
        # Now we have to detect boundaries that are very near each other, because those are a nightmare to handle.
        # They effectively are 1 path anyway, but for an algorithm it becomes like a many possible turning points
        # switching between one boundary and another. It's best to remove them, so first we will get removal
        # candidates- all such double boundaries.
        removal_candidates, filtered_points = self.filter_double_boundaries(boundary_points)
        # I've written processing routines for vertical ones, so to process horizontal double boundaries,
        # let's turn them by 90 degrees.
        removal_candidates_90_deg = {(el[1], el[0]) for el in removal_candidates}
        # Now the way we are going to fix these double boundaries, is by removing one of them and keeping end
        # parts of both of them. So it's a bit like a narrow rectangle, from which we want to remove one long edge
        # and keep the other one and also keep both short edges. That's why we're finding rectangles here. Both
        # horizontal and vertical rectangles.
        rects_vert, single_edge_vertices_vert = self.find_rectangles(removal_candidates)
        rects_horiz, single_edge_vertices_horiz = self.find_rectangles(removal_candidates_90_deg)
        rects_horiz = {(el[1], el[0]) for el in rects_horiz} # restore rotation for the horizontal rectangles
        # find the single long edge to remove
        single_edge_vertices_horiz = {(el[1], el[0]) for el in single_edge_vertices_horiz}

        # Now just simple set arithmetic- take the removal candidates and split away from them the short edges of the
        # rectangles and also one of the long edges.
        removal_candidates = removal_candidates - rects_vert - rects_horiz - single_edge_vertices_vert - single_edge_vertices_horiz

        # Now split away the removal candidates from the boundary point set and we have the boundary that we
        # can process further.
        boundary_points = boundary_points - removal_candidates

        # Finally, take the optimized bounadries and find the biggest polygon that can be detected between them-
        # that's the floor perimeter that we want.
        separated_boundaries = self.get_room_perimeter_points_2nd_pass(boundary_points, self.na)

        return separated_boundaries[-1]

    def get_room_polys(self, house):
        '''
        Returns polygons of all rooms' floors in a house
        :param house:
        :return:
        '''
        room_polys = []
        for room in house["rooms"]:
            room_poly = [(corner["x"], corner["z"]) for corner in room["floorPolygon"]]
            print(room["roomType"] + ": " + str(room_poly))
            room_polys.append(room_poly)
        return room_polys

    def is_wallless_neighbours(self, room_poly1, room_poly2, all_walls):
        neighbours, common_vertices = self.is_neighbours(room_poly1, room_poly2)
        if neighbours:
            # test if there is no wall between rooms. Sometimes though there are rooms which are
            # separated by a short opening, which I would prefer to treat as open door rather than
            # a missing wall. Therefore if the opening is less than 2m, then that will be treated
            # as a door rather than a missing wall.
            if (not self.is_wall_between_rooms(common_vertices, all_walls) and
                self.euclidean_dist(common_vertices[0], common_vertices[1]) > 2.0):
                #print("NO WALL", self.euclidean_dist(common_vertices[0], common_vertices[1]))
                #print("Neighbours: ", room_poly1, " and ", room_poly2, " common vertices: ", common_vertices)
                return True
        return False

    def expand_room_poly_if_needed(self, room_of_placement, house):
        all_room_polys = self.get_room_polys(house)
        all_walls = self.get_house_walls(house)
        this_room_poly = room_of_placement[1]
        resulting_poly = this_room_poly

        for rp in all_room_polys:
            if self.is_wallless_neighbours(this_room_poly, rp, all_walls):
                print("walless neighbour room: ", rp)
                #resulting_poly.extend(rp)
                resulting_poly = unary_union([Polygon(this_room_poly), Polygon(rp)])
                #resulting_poly = rp
                break

        return resulting_poly

    def is_neighbours(self, room_poly1, room_poly2):
        '''
        Tests if two room polygons share a border
        :param room_poly1:
        :param room_poly2:
        :return:
        '''
        common_vertices = []
        # if the same polygons, then return False
        if room_poly2 == room_poly1:
            return False, []

        # otherwise test corners
        for corner in room_poly1:
            if corner in room_poly2:
                common_vertices.append(corner)
        return len(common_vertices) > 1, common_vertices

    def get_house_walls(self, house):
        '''
        Returns all wall lines in a house
        :param house:
        :return:
        '''
        all_walls = []
        for wall in house["walls"]:
            wall_line = {(corner["x"], corner["z"]) for corner in wall["polygon"]}
            empty = False
            if "empty" in wall and wall["empty"]:
                empty = True
            #print(wall["roomId"] + " : " + wall["id"] + " : " + str(wall_line), " : EMPTY = ", empty)
            all_walls.append((wall_line, empty))
        return all_walls

    def is_wall_between_rooms(self, common_vertices, all_walls):
        '''
        Tests if a wall exists between two rooms that share a border.
        :param common_vertices:
        :param all_walls:
        :return:
        '''
        for w, is_empty in all_walls:
            #print("w: ", w, " common_vertices: ", common_vertices)
            if w == set(common_vertices) and not is_empty:
                return True
        return False

    def euclidean_dist(self, p1, p2):
        if len(p1) > 2:
            p1 = (p1[0], p1[2])
        if len(p2) > 2:
            p2 = (p2[0], p2[2])
        return math.sqrt(sum([(a - b)** 2 for a, b in zip(p1, p2)]))

    def create_grid_points_product(self, min_x, max_x, min_y, max_y, step=0.125):
        """
        Create grid points using itertools.product for cleaner code.
        """
        x_values = np.arange(min_x, max_x + step / 2, step)  # Add small epsilon for floating point
        y_values = np.arange(min_y, max_y + step / 2, step)

        points = set()
        for x, y in itertools.product(x_values, y_values):
            points.add((round(x, 2), round(y, 2)))

        points = {(float(p[0]), float(p[1])) for p in points}
        return points


